    /**
     * Ticket Count
     */
    ticket_count: number;
    /**
     * Unit Price Gross
     */
    unit_price_gross: string;
    /**
     * Unit Price Net
     */
    unit_price_net: string;
    /**
     * Unit Vat
     */
    unit_vat: string;
    /**
     * Vat Rate
     */
    vat_rate: string;
    /**
     * Line Net
     */
    line_net: string;
    /**
     * Line Vat
     */
